/* Automated test driver for Lab 11. DO NOT EDIT THIS FILE. */
public class BankAccountTest {

    public static void main(String[] args) {

        TestRunner.section("Constructors and accessors");
        int before = BankAccount.getAccountCount();
        BankAccount a = new BankAccount(1001, "Jane Doe", 250.00);
        TestRunner.check("getId", 1001, a.getId());
        TestRunner.check("getOwner", "Jane Doe", a.getOwner());
        TestRunner.checkNear("getBalance", 250.00, a.getBalance(), 1e-9);

        BankAccount blank = new BankAccount();
        TestRunner.check("default id", 0, blank.getId());
        TestRunner.check("default owner", "Unknown", blank.getOwner());
        TestRunner.checkNear("default balance", 0.0, blank.getBalance(), 1e-9);

        BankAccount negative = new BankAccount(1003, "Test", -75.0);
        TestRunner.checkNear("a negative starting balance is stored as 0",
                0.0, negative.getBalance(), 1e-9);

        TestRunner.section("Static account counter");
        TestRunner.check("three objects were counted", before + 3, BankAccount.getAccountCount());

        TestRunner.section("Mutators");
        a.setId(2002);
        a.setOwner("Jane Q. Doe");
        TestRunner.check("setId", 2002, a.getId());
        TestRunner.check("setOwner", "Jane Q. Doe", a.getOwner());

        TestRunner.section("deposit");
        TestRunner.checkTrue("a valid deposit returns true", a.deposit(100.0));
        TestRunner.checkNear("balance after depositing 100", 350.00, a.getBalance(), 1e-9);
        TestRunner.checkFalse("a zero deposit is rejected", a.deposit(0));
        TestRunner.checkFalse("a negative deposit is rejected", a.deposit(-20));
        TestRunner.checkNear("a rejected deposit leaves the balance unchanged",
                350.00, a.getBalance(), 1e-9);

        TestRunner.section("withdraw");
        TestRunner.checkTrue("a valid withdrawal returns true", a.withdraw(50.0));
        TestRunner.checkNear("balance after withdrawing 50", 300.00, a.getBalance(), 1e-9);
        TestRunner.checkFalse("an overdraft is refused", a.withdraw(1000.0));
        TestRunner.checkNear("a refused withdrawal leaves the balance unchanged",
                300.00, a.getBalance(), 1e-9);
        TestRunner.checkFalse("a negative withdrawal is rejected", a.withdraw(-5));
        TestRunner.checkTrue("withdrawing the entire balance is allowed", a.withdraw(300.0));
        TestRunner.checkNear("balance is now zero", 0.00, a.getBalance(), 1e-9);

        TestRunner.section("Interest");
        BankAccount.setAnnualInterestRate(4.5);
        TestRunner.checkNear("the static rate was stored",
                4.5, BankAccount.getAnnualInterestRate(), 1e-9);
        BankAccount b = new BankAccount(3003, "Sam Lee", 1200.00);
        TestRunner.checkNear("monthly rate = 4.5 / 12 / 100",
                0.00375, b.getMonthlyInterestRate(), 1e-12);
        TestRunner.checkNear("monthly interest on 1200.00", 4.50, b.getMonthlyInterest(), 1e-9);
        TestRunner.checkNear("the rate is shared by every account",
                0.00375, a.getMonthlyInterestRate(), 1e-12);

        TestRunner.section("toString");
        BankAccount c = new BankAccount(1001, "Jane Doe", 250.0);
        TestRunner.check("formatted description", "Account 1001 (Jane Doe): $250.00", c.toString());
        BankAccount d = new BankAccount(7, "A B", 1234.5);
        TestRunner.check("two decimals are always shown", "Account 7 (A B): $1234.50", d.toString());

        TestRunner.exitWithSummary();
    }
}
